insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('377489fb-8e58-4446-acae-120e67ccadb8', '22b01de2-0480-440e-a857-d8695f387713', $$tips duurzamer douchen: 7,2 i.p.v. 10 liter per minuut, 5 i.p.v. 7,4 minuten, vijf keer per week douchen en twee keer 3 liter bij de wastafel$$,
   $$wiskunde-a-vwo-2024-ii-duurzamer-douchen-context1.png$$,
   $$De laatste tientallen jaren wordt er door de overheid aandacht besteed aan duurzamer leven.
Op de website milieucentraal.nl zijn onder andere de volgende tips over duurzamer douchen te vinden: − Gebruik een waterbesparende douchekop, die laat 7,2 liter water per minuut door in plaats van 10 liter water per minuut bij een gewone douchekop. − Douch korter, 5 minuten in plaats van 7,4 minuten. − Douch minder vaak, niet dagelijks, maar vijf keer per week en was je de andere twee keer bij de wastafel. Bij wassen bij de wastafel wordt gemiddeld maar 3 liter water per keer verbruikt.
We bekijken een Nederlander die dagelijks 7,4 minuten met een gewone douchekop doucht. Deze persoon besluit alle hierboven genoemde tips op te volgen. Hierdoor neemt het waterverbruik per week flink af.$$, 'inline'),
  ('05751c75-ba3f-417b-9057-8c060fba33fe', '22b01de2-0480-440e-a857-d8695f387713', $$douchewater 38 °C, 7,2 liter per minuut; 3,2 liter koud water van 10 °C en 4 liter warm water van 60 °C mengen$$,
   $$wiskunde-a-vwo-2024-ii-duurzamer-douchen-context2.png$$,
   $$Het water dat uit een douchekop komt, noemen we douchewater. In het vervolg van deze opgave nemen we het volgende aan: − De temperatuur van douchewater is gelijk aan 38 °C. − Tijdens een douchebeurt wordt 7,2 liter douchewater per minuut gebruikt.
In de meeste huishoudens wordt voor douchewater koud water met warm water vermengd. De verhouding tussen de hoeveelheid koud en warm water bepaalt de temperatuur van het douchewater.
Als er 3,2 liter koud water van 10 °C met 4 liter warm water van 60 °C vermengd wordt, ontstaat er 7,2 liter douchewater van afgerond 38 °C.$$, 'inline'),
  ('88c8dbbc-9da9-4984-a8fc-188e781c6dd2', '22b01de2-0480-440e-a857-d8695f387713', $$douche-wtw: zonder 5,8 cent per minuut, met K = 5,75 + 2,92t; installatie 650 euro, 4 personen, 5 dagen per week, 5 minuten$$,
   $$wiskunde-a-vwo-2024-ii-duurzamer-douchen-context3.png$$,
   $$Water verwarmen kost energie. Door gebruik te maken van douche warmteterugwinning kan er duurzamer worden gedoucht. Bij deze techniek wordt er uit het water dat het riool instroomt warmte gehaald, waardoor er minder energie nodig is om douchewater (van 38 °C) te verkrijgen. Het apparaat waarmee dit gebeurt, wordt een douche-wtw genoemd.
Als er geen douche-wtw geïnstalleerd is, zijn de energiekosten tijdens een douchebeurt gemiddeld 5,8 cent per minuut.
Als er wel een douche-wtw geïnstalleerd is, zijn de energiekosten voor een douchebeurt te berekenen met de formule
K = 5,75 + 2,92t
Hierin is K de energiekosten per douchebeurt in centen en t de tijd in minuten die een douchebeurt duurt, met t groter dan 0.
Een vierpersoonshuishouden laat bij de verbouwing van de badkamer voor 650 euro een douche-wtw installeren. De energiekosten om douchewater te verkrijgen gaan hierdoor omlaag in vergelijking met de situatie zonder douche-wtw. We nemen aan dat alle vier de personen vijf dagen per week douchen en dat elke douchebeurt vijf minuten duurt. Op een bepaald moment zal dit huishouden met de douche-wtw in totaal net zoveel aan energiekosten voor het douchen bespaard hebben als dat de installatie van de douche-wtw gekost heeft.$$, 'inline'),
  ('35be3b0b-3275-4583-a240-8dee0751f4d7', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$huurprijzen 1- en 3-kamerappartementen tegen reistijd tot 42nd Street (figuur 1); vuistregel: per kamer meer 25% hogere huur; reistijd 25 minuten$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context1.png$$,
   $$Wonen in het centrum van een grote stad is in het algemeen duurder dan wonen buiten het centrum. In figuur 1 staan de huurprijzen per maand in 2016 van 1- en 3-kamerappartementen in New York, uitgezet tegen de reistijd met het openbaar vervoer tot 42nd Street, een van de belangrijkste straten in het commerciële centrum. Figuur 1 staat ook vergroot op de uitwerkbijlage.
figuur 1: huurprijs per maand (dollar, 0 tot 10 000) tegen reistijd tot 42nd Street met openbaar vervoer (min., 0 tot 65); open rondjes = 3-kamerappartement, dichte rondjes = 1-kamerappartement
Een punt in figuur 1 stelt niet de huurprijs van één appartement voor, maar de gemiddelde huurprijs van alle appartementen met dezelfde reistijd.
Verhuurders van appartementen gebruiken soms de volgende vuistregel:
Voor elke kamer meer in een appartement stijgt de huurprijs met ongeveer 25%.
We bekijken appartementen met een reistijd van 25 minuten.$$, 'inline'),
  ('518a75a4-71e5-44c7-9c15-6a307c346e10', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$figuur 2 met trendlijnen; 1-kamerappartement met reistijd 15 minuten$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context2.png$$,
   $$In figuur 2 op de uitwerkbijlage zijn aan figuur 1 twee trendlijnen toegevoegd. In het vervolg van deze opgave gaan we uit van deze trendlijnen en niet meer van de individuele datapunten.
We bekijken een 1-kamerappartement met een reistijd van 15 minuten tot 42nd Street. Voor de huurprijs van dit appartement kun je ook een 3-kamerappartement huren. De reistijd tot 42nd Street vanaf dat 3-kamerappartement is wel langer dan de reistijd vanaf het 1-kamerappartement.$$, 'inline'),
  ('41e5f878-c19e-4def-9c13-234fa3592f31', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$trendlijn 3-kamerappartementen: H = 20 367 · r^−0,571$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context3.png$$,
   $$De formule die past bij de trendlijn van de 3-kamerappartementen is:
H = 20 367 · r^(−0,571)
Hierin is H de huurprijs per maand van een 3-kamerappartement in dollars en r de reistijd tot 42nd Street in minuten.$$, 'inline'),
  ('467f5484-ed33-435e-b4ef-7a54c5589e27', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$trendlijn 1-kamerappartementen: P = 5800 − 2572 · log(r); huur daalt minstens $ 75 per minuut extra reistijd$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context4.png$$,
   $$Voor 1-kamerappartementen is de formule van de trendlijn:
P = 5800 − 2572 · log(r)
Hierin is P de huurprijs per maand van een 1-kamerappartement in dollars en r de reistijd tot 42nd Street in minuten.
Er zijn in New York bewoners van een 1-kamerappartement met een bepaalde reistijd tot 42nd Street die theoretisch minstens $ 75 huur zouden kunnen besparen door één minuut verder weg van 42nd Street in een ander 1-kamerappartement te gaan wonen. Ofwel, voor deze bewoners geldt: als de reistijd tot 42nd Street met één minuut toeneemt, dan daalt de huurprijs met minstens $ 75.$$, 'inline'),
  ('1da36510-8f69-4939-af7d-5980463ecdb3', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$uitwerkbijlage bij vraag 4: figuur 1$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context5.png$$,
   $$4
figuur 1 (uitwerkbijlage): huurprijs per maand (dollar) tegen reistijd tot 42nd Street met openbaar vervoer (min.); 3-kamerappartement en 1-kamerappartement$$, 'uitwerkbijlage'),
  ('2bef13a9-b550-4640-8d2e-a77c012d7562', '47908267-65d8-4e09-b5f2-e529fd4ba7f1', $$uitwerkbijlage bij vraag 5: figuur 2 met trendlijnen$$,
   $$wiskunde-a-vwo-2024-ii-wonen-in-new-york-context6.png$$,
   $$5
figuur 2 (uitwerkbijlage): figuur 1 met twee trendlijnen, een voor de 3-kamerappartementen en een voor de 1-kamerappartementen$$, 'uitwerkbijlage'),
  ('79fe0334-bd4d-4ed5-83ad-f6dec44966c7', '14f33100-e926-4a52-b445-203ea8eebb04', $$figuur tijdstip zonsopkomst en zonsondergang in De Bilt; zonsondergang vroegst 16:30 op 12 december (t = 345), laatst 21:00; model Tonder = a + b·sin(c(t − d)) = 18,75 + 2,25 sin(0,0172(t − 71))$$,
   $$wiskunde-a-vwo-2024-ii-daglengte-context1.png$$,
   $$Gedurende het hele jaar veranderen het tijdstip van zonsopkomst en het tijdstip van zonsondergang van dag tot dag. In de figuur zie je periodieke grafieken van de tijdstippen van de zonsopkomst en de zonsondergang in De Bilt voor een jaar met 365 dagen. In de figuur is geen rekening gehouden met de zomertijd.
figuur: tijdstip (0 tot 20+) tegen t (0 tot 365); bovenste grafiek T_onder, onderste grafiek T_op
Het meest vroege tijdstip waarop de zon onder gaat is op 12 december om 16:30 uur. Het meest late tijdstip dat de zon onder gaat is in de zomer om 21:00 uur. Met behulp van deze gegevens kan voor het tijdstip van de zonsondergang een model opgesteld worden van de vorm
T_onder = a + b · sin(c(t − d))
Hierin is T_onder het tijdstip van de zonsondergang in uren en t de tijd in gehele dagen met t = 0 op 1 januari. Bijvoorbeeld bij 12 december hoort t = 345. Dit geeft T_onder = 16,5 dus de zon gaat dan onder om 16:30 uur.
Na afronding van c en d geldt: T_onder = 18,75 + 2,25sin(0,0172(t − 71)).$$, 'inline'),
  ('90939bae-65bb-4ccc-823e-1504dccdf4db', '14f33100-e926-4a52-b445-203ea8eebb04', $$model zonsopkomst: Top = 6,58 + 2,25 sin(0,0172(t − 272))$$,
   $$wiskunde-a-vwo-2024-ii-daglengte-context2.png$$,
   $$Het model voor het tijdstip van de zonsopkomst is:
T_op = 6,58 + 2,25sin(0,0172(t − 272))
Hierin is T_op het tijdstip van de zonsopkomst in uren en t de tijd in gehele dagen met t = 0 op 1 januari.$$, 'inline'),
  ('3f3c5a96-4b89-4cc4-9299-7cf5dcb6bf0b', '14f33100-e926-4a52-b445-203ea8eebb04', $$het vroegste tijdstip van zonsopkomst valt later dan het laatste tijdstip van zonsondergang$$,
   $$wiskunde-a-vwo-2024-ii-daglengte-context3.png$$,
   $$Het meest vroege tijdstip van zonsopkomst valt later in het jaar dan het meest late tijdstip van de zonsondergang.$$, 'inline'),
  ('f09f9a49-4231-467f-96f0-6d0ad2b8a94a', '14f33100-e926-4a52-b445-203ea8eebb04', $$daglengte = tijd tussen zonsopkomst en zonsondergang; op 21 maart neemt de daglengte het meest toe$$,
   $$wiskunde-a-vwo-2024-ii-daglengte-context4.png$$,
   $$Doordat het tijdstip van zonsopkomst en het tijdstip van zonsondergang gedurende het hele jaar veranderen, verandert gedurende het jaar ook de daglengte, dat is de tijd tussen zonsopkomst en zonsondergang.
Op 21 maart begint op het noordelijk halfrond de lente. De daglengte neemt dan het meest toe.$$, 'inline'),
  ('f4e7ace8-5629-4e70-aa4f-4edfa86c7396', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$welvaart Duitsland: verdubbelingstijd 47 jaar in 1850-1940; vanaf 1950 W_D = 6742e^(0,0315t) (formule 1)$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context1.png$$,
   $$In 2020 publiceerde de onderzoeker Charlie Giattino de resultaten van een onderzoek naar de welvaart in een land. Welvaart is een maat voor hoe goed mensen het financieel hebben en wordt (vaak) uitgedrukt in dollars.
Volgens zijn onderzoek was de verdubbelingstijd van de welvaart in Duitsland in de periode 1850-1940 gelijk aan 47 jaar.
Verder volgde uit het onderzoek dat de welvaart in Duitsland vanaf 1950 bij benadering toeneemt volgens de formule:
W_D = 6742e^(0,0315t) (formule 1)
Hierin is W_D de welvaart in Duitsland in dollars en t de tijd in gehele jaren met t = 0 het jaar 1950.
De welvaart nam in de periode 1850-1940 langzamer toe dan dat hij sinds 1950 toeneemt.$$, 'inline'),
  ('a8284ef4-cb10-4aa1-8cb2-4e3455bd0ec5', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$formule 2: U_D = −529,4 ln(W_D) + 6983; welvaart neemt toe met 50%$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context2.png$$,
   $$Giattino deed ook onderzoek naar het verband tussen de welvaart in een land en het aantal uren dat een werknemer in dat land gemiddeld per jaar werkt. Voor Duitsland wordt dit verband gegeven door de formule:
U_D = −529,4ln(W_D) + 6983 (formule 2)
Hierin is U_D het aantal uren dat een werknemer in Duitsland gemiddeld per jaar werkt en W_D de welvaart in Duitsland in dollars. Op basis van formule 2 concludeerde Giattino dat naarmate de welvaart toeneemt, het aantal gewerkte uren afneemt.
Als de welvaart in Duitsland met 50% toeneemt, dan neemt het gemiddeld aantal gewerkte uren per werknemer per jaar met een vast aantal af.$$, 'inline'),
  ('71900782-afea-4b9b-af69-3e044c474c56', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$bewering: aantal gewerkte uren neemt sneller af bij hogere welvaart$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context3.png$$,
   $$Iemand doet de volgende bewering:
Als in Duitsland de welvaart toeneemt dan neemt het gemiddeld aantal gewerkte uren per werknemer per jaar sneller af bij een hogere welvaart dan bij een lagere welvaart.$$, 'inline'),
  ('8caec2e7-64a7-4552-8846-ac74bb33408b', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$formule 1 en 2 combineren tot U_D = pt + q$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context4.png$$,
   $$Door formule 1 en formule 2 te combineren, kan een formule opgesteld worden die het verband benadert tussen het gemiddeld aantal gewerkte uren per werknemer per jaar in Duitsland en het jaar. Deze formule is van de vorm U_D = pt + q.$$, 'inline'),
  ('26e2230f-2b97-41db-8a9d-eb244901dd40', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$welvaart Nederland: 1960 $ 11 529, 2000 $ 34 497; W_N = 8766 · 1,028^t (formule 3)$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context5.png$$,
   $$In Nederland groeit de welvaart bij benadering ook exponentieel sinds 1950. In 1960 was de welvaart in Nederland $ 11 529 en in 2000 was dat $ 34 497. Uit de gegevens volgt dat de welvaart in Nederland kan worden beschreven met de formule:
W_N = 8766 · 1,028^t (formule 3)
Hierin is W_N de welvaart in Nederland in dollars en t de tijd in gehele jaren met t = 0 het jaar 1950.
In formule 3 is de beginhoeveelheid afgerond op helen tot 8766 en de jaarlijkse groeifactor is afgerond op drie decimalen tot 1,028.$$, 'inline'),
  ('6383ef54-a848-4f77-b20a-95ff9c1875bc', 'abf8bd3f-e437-49ad-90b1-fa4ff93cc786', $$vanaf een bepaald moment nam de welvaart in Duitsland sneller toe dan in Nederland$$,
   $$wiskunde-a-vwo-2024-ii-minder-werken-context6.png$$,
   $$In 1950 was de welvaart in Nederland groter dan in Duitsland. Bovendien nam de welvaart in Nederland toen sneller toe dan die in Duitsland. Decennia later haalde de welvaart in Duitsland die in Nederland in. Hieruit volgt dat vanaf een bepaald moment de welvaart in Duitsland sneller toenam dan die in Nederland.$$, 'inline'),
  ('5be261b4-a42c-4dc7-83b1-146fc0f50868', '0acef673-7e55-416e-8bdf-d798a3eaacd7', $$krattenbrug: foto en afbeelding; twee torens van 29 lagen; A(n) = 3,5n + 3,5 (oneven laag) en A(n) = 3,5n + 3 (even laag) voor de bovenste 11 lagen$$,
   $$wiskunde-a-vwo-2024-ii-krattenbrug-context1.png$$,
   $$Studenten van de Technische Universiteit Eindhoven hebben in 2016 een brug van kratten gebouwd. Zie de foto. Naast de foto zie je ook een afbeelding van een computeranimatie uit de ontwerpfase van de krattenbrug.
foto en afbeelding van de krattenbrug
De krattenbrug bestaat uit twee even grote torens met daartussen een overspanning.
Elke toren bestaat uit 29 lagen gestapelde kratten. De bovenste laag geven we nummer 1, de laag direct daaronder nummer 2, enzovoorts.
Voor de bovenste 11 lagen geldt voor het aantal kratten per laag:
A(n) = 3,5n + 3,5 voor lagen met een oneven nummer
A(n) = 3,5n + 3 voor lagen met een even nummer
Hierin is A(n) het aantal kratten en n het nummer van de laag.
Elke laag (behalve de bovenste laag natuurlijk) met een oneven nummer heeft eenzelfde aantal kratten meer dan de direct daarboven gelegen laag met een even nummer.$$, 'inline'),
  ('3440ba2d-ac1d-4579-891f-e126430a5b27', '0acef673-7e55-416e-8bdf-d798a3eaacd7', $$overspanning 4950 kratten; laag 12 t/m 29 evenveel kratten als laag 11$$,
   $$wiskunde-a-vwo-2024-ii-krattenbrug-context2.png$$,
   $$Neem aan dat voor de overspanning in totaal 4950 kratten zijn gebruikt. Voor beide torens geldt dat laag 12 tot en met laag 29 elk evenveel kratten bevatte als laag 11.$$, 'inline'),
  ('25807319-58a0-4e3f-b49b-81c20f3ae9f8', '0acef673-7e55-416e-8bdf-d798a3eaacd7', $$figuur boog in assenstelsel: breedte 26,7 m, hoogte 5,3 m, Dommel 9,0 m breed; y = a·x² + b; persoon van 1,90 m op 6 m van de waterkant$$,
   $$wiskunde-a-vwo-2024-ii-krattenbrug-context3.png$$,
   $$Op de foto is te zien dat de krattenbrug over een rivier is gebouwd. Deze rivier, de Dommel, stroomt midden onder de brug door. In de figuur is de situatie schematisch weergegeven in een assenstelsel. In deze figuur zijn van de brug alleen de torens en de onderkant van de overspanning weergegeven. Deze onderkant noemen we de boog.
figuur: boog tussen twee torens boven de grond (x-as), y-as door het hoogste punt; hoogte 5,3 m, Dommel 9,0 m breed, boog 26,7 m breed
In de figuur is de grond als x-as genomen en gaat de y-as door het hoogste punt van de boog.
Verder zijn de volgende gegevens bekend, zie de figuur: − De boog is 26,7 meter breed. − De maximale hoogte van de boog is 5,3 meter ten opzichte van de grond. − De Dommel is 9,0 meter breed.
Voor de boog kan een formule worden opgesteld van de vorm y = a · x² + b.
Een persoon met een lengte van 1,90 meter loopt op een afstand van 6 meter van de waterkant onder de brug door.$$, 'inline'),
  ('616b7e7c-db2b-440c-a759-c71180973406', 'eda5fe15-c38c-4151-aeab-b458a7a05043', $$spel Quoridor: speelbord 9 bij 9 velden, foto 1 en foto 2; muurtjes van twee velden lang; midden op het bord 4 plaatsen minder, aan de rand 3 plaatsen minder$$,
   $$wiskunde-a-vwo-2024-ii-quoridor-context1.png$$,
   $$In deze opgave bekijken we de tweepersoonsvariant van het spel Quoridor dat gespeeld wordt met een witte en een zwarte pion en meerdere muurtjes op een speelbord van negen bij negen velden. Zie foto 1.
foto 1: speelbord met twee pionnen en twee muurtjes
Het doel van het spel is om met je pion zo snel mogelijk de overkant van het speelbord te bereiken. Om beurten doen de spelers een zet. Een zet bestaat uit het verplaatsen van de eigen pion of het neerzetten van een nieuw muurtje. In deze opgave kijken we alleen naar het neerzetten van de eerste twee muurtjes waarbij de pionnen niet verplaatst worden.
De velden zijn vierkantjes en de muurtjes worden in gleuven tussen de velden neergezet. De muurtjes zijn identiek en even lang als twee velden en één gleuf. De muurtjes worden zo neergezet dat zich aan elke zijde van het muurtje precies twee velden en een gleuf bevinden. Zie foto 2. De letters in foto 2 staan niet echt op het speelbord, maar die zijn toegevoegd om de velden een naam te geven.
foto 2: velden A, B, C, D (links) en E, F, G, H (rechts) met een muurtje in de gleuf rechts van B en C
Muurtjes kunnen niet geheel of gedeeltelijk over elkaar heen neergezet worden, daarom zijn er met elk neergezet muurtje minder mogelijkheden om een volgend muurtje neer te zetten.
Het muurtje op foto 2 staat ergens midden op het speelbord. Het volgende muurtje kan niet op een van de volgende vier plaatsen neergezet worden: rechts van A en B, rechts van B en C, rechts van C en D, onder B en F.
Als het eerste muurtje ergens midden op het bord neergezet is, dan zijn er dus vier plaatsen minder om het tweede muurtje neer te zetten. Grenst het eerste muurtje met een uiteinde aan de rand van het speelbord, dan zijn er drie plaatsen minder om het tweede muurtje neer te zetten.
Op foto 1 zie je een mogelijke situatie waarin beide spelers een muurtje hebben neergezet en de witte en zwarte pion nog op hun startpositie staan.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
